package webhook

import (
	"context"
	"sync"
	"time"
)

// Limiter is a per-host token bucket. Each host gets its own bucket so one
// slow subscriber cannot starve the rest.
type Limiter struct {
	mu      sync.Mutex
	rate    float64 // tokens per second
	burst   int
	buckets map[string]*bucket
	now     func() time.Time
}

type bucket struct {
	tokens float64
	last   time.Time
}

// NewLimiter returns a Limiter allowing rate requests per second per host,
// with bursts of up to burst requests.
func NewLimiter(rate float64, burst int) *Limiter {
	return &Limiter{rate: rate, burst: burst, buckets: map[string]*bucket{}, now: time.Now}
}

// Wait blocks until host may send one request, or ctx is done.
func (l *Limiter) Wait(ctx context.Context, host string) error {
	for {
		d := l.reserve(host)
		if d == 0 {
			return nil
		}
		t := time.NewTimer(d)
		select {
		case <-ctx.Done():
			t.Stop()
			return ctx.Err()
		case <-t.C:
		}
	}
}

// reserve takes a token for host if one is available and returns 0, or
// returns how long to wait for the next one.
func (l *Limiter) reserve(host string) time.Duration {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.now()
